/**
 * FILE: concept_4_market_sentiment_thermometer.js
 * THEME: Finance & Investment — Market Sentiment Thermometer & Financial Heat Gauge
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Harmonic phase multiples for 100% seamless 20-second loop
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau + currentScene * 0;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;

  // Synchronized master market sentiment level (0.0 = Cool Value, 1.0 = Hot Bullish)
  const sentimentNorm = 0.5 - 0.42 * Math.cos(p1) + 0.06 * Math.sin(p3);

  // Color Palette (Crisp Commercial Flat Vector, Zero Glow)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#162035',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    glassShell: '#E2E8F0',
    glassInner: '#F8FAFC',
    slateDark: '#334155',
    slateMid: '#64748B',
    coldBlueLight: '#BAE6FD',
    coldBlueMid: '#22A7F0',
    coldBlueDark: '#0284C7',
    tealMid: '#14B8A6',
    emeraldLight: '#A7F3D0',
    emeraldMid: '#22C55E',
    emeraldDark: '#15803D',
    goldLight: '#FEF08A',
    goldMid: '#FACC15',
    goldDark: '#EAB308',
    goldDeep: '#CA8A04',
    hotOrangeLight: '#FED7AA',
    hotOrangeMid: '#FB923C',
    hotOrangeDark: '#EA580C',
    hotRedMid: '#F87171',
    hotRedDark: '#DC2626'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Emblem
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 13 * scaleSize;
    const h = 20 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Gold Coin Medallion
  function drawGoldMedallion(centerX, centerY, radius, dollarScale) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, tau);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.arc(centerX, centerY, radius * 0.74, 0, tau);
    fillAndStroke(COL.goldLight, COL.outline, 2.5 * s);

    drawVectorDollar(centerX, centerY, dollarScale, COL.outline, 3.2 * s);
  }

  // Helper: Side-View Stacked Coin Cylinder
  function drawCoinCylinder(centerX, topY, coinW, coinH) {
    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    roundedRectPath(centerX - coinW * 0.40, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldLight, null, 0);

    roundedRectPath(centerX + coinW * 0.20, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldDeep, null, 0);

    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(null, COL.outline, thinStrokeW);
  }

  // Helper: Continuous Seamless Thermometer Outline Path (Bulb + Vertical Stem)
  function traceThermometerPath(centerX, topArcCY, bulbCenterY, stemHalfW, bulbR) {
    const joinAngle = Math.asin(stemHalfW / bulbR);
    ctx.beginPath();
    ctx.arc(centerX, topArcCY, stemHalfW, Math.PI, 0, false);
    ctx.arc(centerX, bulbCenterY, bulbR, -Math.PI * 0.5 + joinAngle, Math.PI * 1.5 - joinAngle, false);
    ctx.closePath();
  }

  // =========================================================================
  // 2. STRUCTURAL BASELINE PLATFORM & NON-INTERSECTING TELEMETRY BRIDGES
  // =========================================================================
  const baseLineY = cy + 395 * s;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 735 * s, baseLineY);
  ctx.lineTo(cx + 735 * s, baseLineY);
  ctx.stroke();

  // Outer baseline accent ticks
  const tickShift = Math.sin(p2) * 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 810 * s - tickShift, baseLineY);
  ctx.lineTo(cx - 760 * s - tickShift, baseLineY);
  ctx.moveTo(cx + 760 * s + tickShift, baseLineY);
  ctx.lineTo(cx + 810 * s + tickShift, baseLineY);
  ctx.stroke();

  // Sub-platform line
  ctx.beginPath();
  ctx.moveTo(cx - 360 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 360 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Dedicated Horizontal Data Bridges in Lower Corridor (y = cy + 205*s)
  const bridgeY = cy + 205 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 275 * s, bridgeY);
  ctx.lineTo(cx - 210 * s, bridgeY);
  ctx.moveTo(cx + 225 * s, bridgeY);
  ctx.lineTo(cx + 275 * s, bridgeY);
  ctx.stroke();

  const bProgL = (sceneProgress * 4) % 1;
  ctx.beginPath();
  ctx.arc(cx - 268 * s + bProgL * 50 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.coldBlueMid, COL.outline, 2.5 * s);

  const bProgR = (sceneProgress * 4 + 0.5) % 1;
  ctx.beginPath();
  ctx.arc(cx + 232 * s + bProgR * 36 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.hotOrangeMid, COL.outline, 2.5 * s);

  // =========================================================================
  // 3. LEFT-TOP ZONE: MARKET SENTIMENT SPEEDOMETER & VOLATILITY GAUGE CARD
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 4.5 * s;
  const ltX = cx - 685 * s;
  const ltY = cy - 360 * s + ltFloatY;
  const ltW = 400 * s;
  const ltH = 315 * s;

  roundedRectPath(ltX, ltY, ltW, ltH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Top Header Strip inside Left-Top Card
  roundedRectPath(ltX + 18 * s, ltY + 18 * s, ltW - 36 * s, 46 * s, 12 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  const statusCols = [COL.coldBlueMid, COL.goldMid, COL.hotOrangeMid];
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(ltX + 40 * s + d * 24 * s, ltY + 41 * s, 7 * s, 0, tau);
    fillAndStroke(statusCols[d], COL.outline, 2.5 * s);
  }

  roundedRectPath(ltX + 118 * s, ltY + 35 * s, 155 * s, 12 * s, 6 * s);
  fillAndStroke(COL.slateDark, null, 0);

  const headerPillCol = sentimentNorm > 0.62 ? COL.hotOrangeMid : (sentimentNorm > 0.38 ? COL.goldMid : COL.coldBlueMid);
  roundedRectPath(ltX + ltW - 102 * s, ltY + 27 * s, 68 * s, 28 * s, 8 * s);
  fillAndStroke(headerPillCol, COL.outline, 2.5 * s);

  // Semi-Circular Market Heat Speedometer
  const gCX = ltX + ltW * 0.5;
  const gCY = ltY + 205 * s;
  const gOuterR = 106 * s;
  const gInnerR = 58 * s;

  const zoneAngles = [Math.PI, Math.PI * 1.25, Math.PI * 1.50, Math.PI * 1.75, Math.PI * 2];
  const zoneColors = [COL.coldBlueMid, COL.emeraldMid, COL.goldMid, COL.hotOrangeMid];

  for (let z = 0; z < 4; z++) {
    ctx.beginPath();
    ctx.arc(gCX, gCY, gOuterR, zoneAngles[z], zoneAngles[z + 1], false);
    ctx.arc(gCX, gCY, gInnerR, zoneAngles[z + 1], zoneAngles[z], true);
    ctx.closePath();
    fillAndStroke(zoneColors[z], COL.outline, thinStrokeW);
  }

  // Synchronized Gauge Needle
  const needleAngle = Math.PI + sentimentNorm * Math.PI;
  const needleLen = 86 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 6 * s;
  ctx.beginPath();
  ctx.moveTo(gCX, gCY);
  ctx.lineTo(gCX + Math.cos(needleAngle) * needleLen, gCY + Math.sin(needleAngle) * needleLen);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(gCX, gCY, 18 * s, 0, tau);
  fillAndStroke(COL.slateDark, COL.outline, thinStrokeW);

  // 3 Bottom Telemetry Metric Pills
  const mPillW = 104 * s;
  const mPillGap = 20 * s;
  for (let p = 0; p < 3; p++) {
    const px = ltX + 24 * s + p * (mPillW + mPillGap);
    roundedRectPath(px, ltY + 252 * s, mPillW, 38 * s, 10 * s);
    fillAndStroke(p === 2 ? headerPillCol : COL.surfaceLight, COL.outline, 2.8 * s);

    roundedRectPath(px + 18 * s, ltY + 266 * s, mPillW - 36 * s, 10 * s, 5 * s);
    fillAndStroke(COL.outline, null, 0);
  }

  // =========================================================================
  // 4. LEFT-BOTTOM ZONE: INFLATION ANALYTICS CLIPBOARD & GOLD RESERVES
  // =========================================================================
  const lbFloatY = Math.cos(p2) * 4 * s;
  const lbX = cx - 685 * s;
  const lbY = cy + 25 * s + lbFloatY;
  const lbW = 400 * s;
  const lbCardH = 190 * s;

  roundedRectPath(lbX, lbY, lbW, lbCardH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  roundedRectPath(lbX + 18 * s, lbY + 18 * s, 118 * s, lbCardH - 36 * s, 14 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  const ringCX = lbX + 77 * s;
  const ringCY = lbY + 78 * s;
  ctx.beginPath();
  ctx.arc(ringCX, ringCY, 34 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);
  drawUpArrow(ringCX, ringCY, 22 * s, COL.outline, 4 * s);

  roundedRectPath(lbX + 36 * s, lbY + 132 * s, 82 * s, 12 * s, 6 * s);
  fillAndStroke(COL.slateDark, null, 0);
  roundedRectPath(lbX + 46 * s, lbY + 150 * s, 62 * s, 10 * s, 5 * s);
  fillAndStroke(COL.slateMid, null, 0);

  const rateStartX = lbX + 156 * s;
  const rateTrackW = 222 * s;
  const rateColors = [COL.coldBlueMid, COL.goldMid, COL.hotOrangeMid];
  for (let r = 0; r < 3; r++) {
    const ry = lbY + 32 * s + r * 50 * s;
    roundedRectPath(rateStartX, ry, 88 * s, 9 * s, 4.5 * s);
    fillAndStroke(COL.slateMid, null, 0);

    roundedRectPath(rateStartX, ry + 15 * s, rateTrackW, 20 * s, 10 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.5 * s);

    const rFill = (0.45 + 0.38 * Math.sin(p2 + r * 1.1)) * (rateTrackW - 6 * s);
    roundedRectPath(rateStartX + 3 * s, ry + 18 * s, rFill, 14 * s, 7 * s);
    fillAndStroke(rateColors[r], null, 0);
  }

  // Lower Gold Bullion & Coin Pedestal on baseLineY
  const pedLX = lbX;
  const pedLW = lbW;
  const pedLH = 24 * s;
  const pedLY = baseLineY - pedLH;

  roundedRectPath(pedLX, pedLY, pedLW, pedLH, 8 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  function drawBullionBar(centerX, bottomY, barW, barH) {
    const topW = barW * 0.78;
    ctx.beginPath();
    ctx.moveTo(centerX - barW * 0.5, bottomY);
    ctx.lineTo(centerX - topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + barW * 0.5, bottomY);
    ctx.closePath();
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.moveTo(centerX - topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.42, bottomY - 7 * s);
    ctx.lineTo(centerX - topW * 0.42, bottomY - 7 * s);
    ctx.closePath();
    fillAndStroke(COL.goldLight, null, 0);
  }

  const bulCX = lbX + 86 * s;
  drawBullionBar(bulCX, pedLY, 126 * s, 38 * s);
  drawBullionBar(bulCX, pedLY - 38 * s, 110 * s, 36 * s);

  const stackLCX = lbX + 220 * s;
  const cH = 24 * s;
  for (let c = 0; c < 4; c++) {
    drawCoinCylinder(stackLCX, pedLY - (c + 1) * cH, 86 * s, cH);
  }

  const medLCX = lbX + 336 * s;
  const medLCY = pedLY - 64 * s + Math.sin(p2) * 4 * s;
  roundedRectPath(medLCX - 22 * s, pedLY - 16 * s, 44 * s, 16 * s, 5 * s);
  fillAndStroke(COL.goldDeep, COL.outline, thinStrokeW);
  drawGoldMedallion(medLCX, medLCY, 44 * s, 1.25 * s);

  // =========================================================================
  // 5. CENTER ZONE: MARKET SENTIMENT THERMOMETER, CALLOUT BUBBLE & ZONE PILLS
  // =========================================================================
  const thermCX = cx + 42 * s;
  const topArcCY = cy - 305 * s;
  const bulbCY = cy + 242 * s;
  const outerStemHalfW = 48 * s;
  const outerBulbR = 90 * s;
  const innerStemHalfW = 32 * s;
  const innerBulbR = 72 * s;

  // 5A. Thermometer Pedestal Stand on baseLineY
  roundedRectPath(thermCX - 64 * s, cy + 318 * s, 128 * s, 42 * s, 10 * s);
  fillAndStroke(COL.slateMid, COL.outline, strokeW);

  roundedRectPath(thermCX - 108 * s, baseLineY - 38 * s, 216 * s, 38 * s, 12 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  roundedRectPath(thermCX - 82 * s, baseLineY - 22 * s, 164 * s, 10 * s, 5 * s);
  fillAndStroke(COL.coldBlueMid, null, 0);

  // 5B. Thermometer Outer Glass Housing Shell
  traceThermometerPath(thermCX, topArcCY, bulbCY, outerStemHalfW, outerBulbR);
  fillAndStroke(COL.glassShell, COL.outline, strokeW);

  // Thermometer Inner Chamber Background
  traceThermometerPath(thermCX, topArcCY, bulbCY, innerStemHalfW, innerBulbR);
  fillAndStroke(COL.glassInner, COL.outline, thinStrokeW);

  // 5C. Clipped Thermal Gradient Liquid & Full Blue Bulb Fill
  const liquidMinY = cy + 88 * s;
  const liquidMaxY = cy - 245 * s;
  const liquidY = liquidMinY - sentimentNorm * (liquidMinY - liquidMaxY);

  ctx.save();
  traceThermometerPath(thermCX, topArcCY, bulbCY, innerStemHalfW, innerBulbR);
  ctx.clip();

  // Multi-Stop Vertical Thermal Gradient:
  // Keeps the entire lower bulb 100% rich blue while transitioning smoothly up the stem
  const liqGrad = ctx.createLinearGradient(0, bulbCY + innerBulbR, 0, topArcCY - innerStemHalfW);
  liqGrad.addColorStop(0.00, COL.coldBlueDark);
  liqGrad.addColorStop(0.26, COL.coldBlueMid);
  liqGrad.addColorStop(0.55, COL.goldMid);
  liqGrad.addColorStop(0.80, COL.hotOrangeMid);
  liqGrad.addColorStop(1.00, COL.hotRedMid);

  const leftStemX = thermCX - innerStemHalfW - 8 * s;
  const rightStemX = thermCX + innerStemHalfW + 8 * s;
  const fullBulbLeftX = thermCX - innerBulbR - 16 * s;
  const fullBulbRightX = thermCX + innerBulbR + 16 * s;
  const fullBulbBottomY = bulbCY + innerBulbR + 16 * s;
  const spanW = rightStemX - leftStemX;
  const waveSteps = 24;
  const waveAmp = 5 * s;

  // Back Meniscus Wave Layer (Spans full bulb width at bottom so bulb is 100% filled)
  ctx.beginPath();
  ctx.moveTo(fullBulbLeftX, fullBulbBottomY);
  ctx.lineTo(fullBulbLeftX, liquidY);
  for (let i = 0; i <= waveSteps; i++) {
    const u = i / waveSteps;
    const wx = leftStemX + u * spanW;
    const wy = liquidY - 4 * s + Math.sin(u * Math.PI * 1.5 - p4 + 1.2) * (waveAmp * 0.8);
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(fullBulbRightX, liquidY);
  ctx.lineTo(fullBulbRightX, fullBulbBottomY);
  ctx.closePath();
  ctx.fillStyle = sentimentNorm > 0.6 ? COL.hotOrangeDark : (sentimentNorm > 0.35 ? COL.goldDeep : COL.coldBlueDark);
  ctx.fill();

  // Front Gradient Liquid Fill (Spans full bulb width from fullBulbLeftX to fullBulbRightX)
  ctx.beginPath();
  ctx.moveTo(fullBulbLeftX, fullBulbBottomY);
  ctx.lineTo(fullBulbLeftX, liquidY);
  for (let i = 0; i <= waveSteps; i++) {
    const u = i / waveSteps;
    const wx = leftStemX + u * spanW;
    const wy = liquidY + Math.sin(u * Math.PI * 1.5 + p4) * waveAmp;
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(fullBulbRightX, liquidY);
  ctx.lineTo(fullBulbRightX, fullBulbBottomY);
  ctx.closePath();
  ctx.fillStyle = liqGrad;
  ctx.fill();

  // Crisp Top Meniscus Outline across the stem
  ctx.beginPath();
  for (let i = 0; i <= waveSteps; i++) {
    const u = i / waveSteps;
    const wx = leftStemX + u * spanW;
    const wy = liquidY + Math.sin(u * Math.PI * 1.5 + p4) * waveAmp;
    if (i === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 3 * s;
  ctx.stroke();

  // Rising Thermal Micro-Bubbles inside Thermometer Stem (Strictly below liquidY)
  for (let b = 0; b < 3; b++) {
    const bProg = (sceneProgress * 4 + b * 0.333) % 1;
    const bStartY = bulbCY - 28 * s;
    const bEndY = liquidY + 18 * s;
    if (bEndY < bStartY) {
      const by = bStartY - bProg * (bStartY - bEndY);
      const bx = thermCX + (b - 1) * 11 * s + Math.sin(p4 + b * 2) * 2.5 * s;
      const br = (4.5 + (b % 2) * 1.5) * s * Math.sin(bProg * Math.PI);
      if (br > 0.8 * s) {
        ctx.beginPath();
        ctx.arc(bx, by, br, 0, tau);
        fillAndStroke(COL.surfaceWhite, COL.outline, 2 * s);
      }
    }
  }

  // Graduation Scale Tick Marks on Left Inside Wall of Thermometer Tube
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 3.5 * s;
  const tickCount = 11;
  const firstTickY = cy - 265 * s;
  const tickStepY = 36 * s;
  for (let tk = 0; tk < tickCount; tk++) {
    const ty = firstTickY + tk * tickStepY;
    const tLen = (tk % 2 === 0 ? 18 : 11) * s;
    ctx.beginPath();
    ctx.moveTo(thermCX - innerStemHalfW, ty);
    ctx.lineTo(thermCX - innerStemHalfW + tLen, ty);
    ctx.stroke();
  }

  // Right Vertical Specular Glass Highlight inside Stem
  roundedRectPath(thermCX + innerStemHalfW - 12 * s, topArcCY + 10 * s, 6 * s, (bulbCY - innerBulbR) - topArcCY - 20 * s, 3 * s);
  fillAndStroke('rgba(255, 255, 255, 0.65)', null, 0);

  // Curved Specular Highlight Crescent on Bottom-Right of Blue Bulb
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.72)';
  ctx.lineWidth = 9 * s;
  ctx.beginPath();
  ctx.arc(thermCX, bulbCY, innerBulbR - 16 * s, 0.15, 0.95, false);
  ctx.stroke();

  ctx.restore();

  // Re-stroke Inner Chamber Outline for razor-sharp edge
  traceThermometerPath(thermCX, topArcCY, bulbCY, innerStemHalfW, innerBulbR);
  fillAndStroke(null, COL.outline, thinStrokeW);

  // Center Gold Dollar Medallion Core inside Thermometer Bulb
  const bulbMedScale = 1 + 0.04 * Math.sin(p4);
  drawGoldMedallion(thermCX, bulbCY, 34 * s * bulbMedScale, 1.05 * s);

  // 5D. Synchronized Tracking Callout Bubble (Left of Thermometer Stem)
  const calloutCX = cx - 102 * s;
  const calloutCY = liquidY;
  const calloutR = 52 * s;
